// Package store persists document metadata in PostgreSQL.
package store

import (
	"context"
	"database/sql"
	"embed"
	"errors"
	"fmt"
	"io/fs"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"
	"github.com/pressly/goose/v3/lock"

	"github.com/pklnx/paperless-go/internal/store/db"
)

//go:embed migrations/*.sql
var migrationsFS embed.FS

// Store wraps a PostgreSQL connection pool. Queries are generated by sqlc
// from internal/store/queries (see sqlc.yaml).
type Store struct {
	pool *pgxpool.Pool
	// g is the pool behind the guard (locking.go): outside a transaction
	// it refuses every writer of the owner tables. q runs on it.
	g guardedDB
	q *db.Queries
	// sq runs the search queries as unnamed statements (search.go);
	// searchDB wraps a guarded transaction the same way.
	sq       *db.Queries
	searchDB func(guardedDB) db.DBTX
	// userAgents caches the IDs of audit log user agents.
	userAgents userAgentCache
	// gate keeps writers of one owner that wait for each other off the
	// pool (ownergate.go). The worker and the handlers share it.
	gate *ownerGate

	// Now is the clock of every trash decision (documents_trash.go): the
	// time a document is trashed or its purge is asked for, and whether
	// a trashed document is due for purge. nil is time.Now. Tests set it
	// before the store is used.
	Now func() time.Time
	// TrashRetention is how long a trashed document stays before it is
	// due for purge (PAPERLESS_GO_TRASH_RETENTION); Open sets
	// DefaultTrashRetention. It is read at every decision, so a shorter
	// one applies to documents already in the trash. Set it before the
	// store is used.
	TrashRetention time.Duration
	// SearchTimeout bounds each search query (SearchDocuments, through
	// statement_timeout in its read-only transaction); Open sets
	// DefaultSearchTimeout. A search that runs longer fails with
	// ErrSearchTooBroad. Set it before the store is used.
	SearchTimeout time.Duration
}

// Open connects to the database.
func Open(ctx context.Context, url string) (*Store, error) {
	pool, err := pgxpool.New(ctx, url)
	if err != nil {
		return nil, err
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("connect to database: %w", err)
	}
	g := guardedDB{d: pool}
	s := &Store{
		pool: pool, g: g, q: db.New(g), gate: newOwnerGate(), searchDB: func(d guardedDB) db.DBTX { return unnamedStatements{d} },
		TrashRetention: DefaultTrashRetention, SearchTimeout: DefaultSearchTimeout,
	}
	s.sq = db.New(s.searchDB(g))
	return s, nil
}

// Close releases all connections.
func (s *Store) Close() { s.pool.Close() }

// Ping checks that the database answers.
func (s *Store) Ping(ctx context.Context) error { return s.pool.Ping(ctx) }

// Migrate applies all pending schema migrations and rebuilds the
// collation-dependent indexes if the database locale changed (see
// collation.go).
func (s *Store) Migrate(ctx context.Context) ([]string, error) {
	r, err := s.MigrateAndRebuild(ctx)
	return r.Applied, err
}

// MigrateReport is what MigrateAndRebuild did.
type MigrateReport struct {
	Applied  []string // migrations applied
	Rebuilt  []string // indexes rebuilt after a change of the database locale
	Warnings []string // for the operator; nothing failed
}

// MigrateAndRebuild is Migrate with a report. It refuses PostgreSQL older
// than MinServerVersion before anything else. The collation-dependent
// indexes are rebuilt before the migrations run, so these work on indexes
// in order, and the fingerprint is stored after them, once its table
// exists.
func (s *Store) MigrateAndRebuild(ctx context.Context) (MigrateReport, error) {
	var r MigrateReport
	if err := s.CheckServerVersion(ctx); err != nil {
		return r, err
	}
	builtFor, rebuilt, warnings, err := s.ensureCollation(ctx, "")
	r.Rebuilt, r.Warnings = rebuilt, warnings
	if err != nil {
		return r, err
	}
	err = s.withMigrations(func(p *goose.Provider) error {
		results, err := p.Up(ctx)
		for _, res := range results {
			r.Applied = append(r.Applied, res.Source.Path)
		}
		return err
	})
	if err != nil {
		return r, err
	}
	// Its warnings repeat the first call's.
	_, rebuilt, _, err = s.ensureCollation(ctx, builtFor)
	r.Rebuilt = append(r.Rebuilt, rebuilt...)
	return r, err
}

// MigrateDown rolls back the most recently applied migration. This usually
// drops data. It returns the migration that was rolled back.
func (s *Store) MigrateDown(ctx context.Context) (string, error) {
	var rolledBack string
	err := s.withMigrations(func(p *goose.Provider) error {
		r, err := p.Down(ctx)
		if errors.Is(err, goose.ErrNoNextVersion) {
			return errors.New("no migration to roll back")
		}
		if err != nil {
			return err
		}
		rolledBack = r.Source.Path
		return nil
	})
	return rolledBack, err
}

// MigrateDownTo rolls back every applied migration newer than version, newest
// first. Tests use it to reach the schema before a migration however many
// came after it; like MigrateDown, it usually drops data.
func (s *Store) MigrateDownTo(ctx context.Context, version int64) error {
	return s.withMigrations(func(p *goose.Provider) error {
		_, err := p.DownTo(ctx, version)
		return err
	})
}

// MigrationStatus describes one known migration.
type MigrationStatus struct {
	Path      string
	Applied   bool
	AppliedAt time.Time
}

// MigrationStatus lists all migrations and whether they are applied.
func (s *Store) MigrationStatus(ctx context.Context) ([]MigrationStatus, error) {
	var out []MigrationStatus
	err := s.withMigrations(func(p *goose.Provider) error {
		statuses, err := p.Status(ctx)
		if err != nil {
			return err
		}
		for _, st := range statuses {
			out = append(out, MigrationStatus{
				Path:      st.Source.Path,
				Applied:   st.State == goose.StateApplied,
				AppliedAt: st.AppliedAt,
			})
		}
		return nil
	})
	return out, err
}

// SchemaVersions returns the schema version of the database and the
// newest migration this binary embeds. A database ahead of the binary was
// migrated by a newer version.
func (s *Store) SchemaVersions(ctx context.Context) (database, known int64, err error) {
	err = s.withMigrations(func(p *goose.Provider) error {
		if database, err = p.GetDBVersion(ctx); err != nil {
			return err
		}
		for _, src := range p.ListSources() {
			known = max(known, src.Version)
		}
		return nil
	})
	return database, known, err
}

func (s *Store) withMigrations(fn func(*goose.Provider) error) error {
	sub, err := fs.Sub(migrationsFS, "migrations")
	if err != nil {
		return err
	}
	// A session lock keeps two migrate runs at the same time from
	// applying the same version. The second retries every second for up
	// to 5 minutes (goose's default timeout, retried more often).
	locker, err := lock.NewPostgresSessionLocker(lock.WithLockTimeout(1, 300))
	if err != nil {
		return err
	}
	sqlDB := stdlib.OpenDBFromPool(s.pool)
	defer func(d *sql.DB) { _ = d.Close() }(sqlDB)
	provider, err := goose.NewProvider(goose.DialectPostgres, sqlDB, sub, goose.WithSessionLocker(locker))
	if err != nil {
		return err
	}
	return fn(provider)
}

// Installation identifies this installation.
type Installation struct {
	ID        string
	CreatedAt time.Time
}

// Installation returns the row created by the first migration.
func (s *Store) Installation(ctx context.Context) (*Installation, error) {
	row, err := s.q.GetInstallation(ctx)
	if err != nil {
		return nil, err
	}
	return &Installation{ID: row.ID.String(), CreatedAt: row.CreatedAt}, nil
}
